090,"utf8":"  }\n  /* Check if there's testing sample */\n  if (nbTestSamples < 1) {\n    DISPLAYLEVEL(1, \"Total number of testing samples is %u and is invalid.\", nbTestSamples);\n    return 0;\n  }\n  /* Zero the context */\n  memset(ctx, 0, sizeof(*ctx));\n  DISPLAYLEVEL(2, \"Training on %u samples of total size %u\\n\", nbTrainSamples,\n               (U32)trainingSamplesSize);\n  DISPLAYLEVEL(2, \"Testing on %u samples of total size %u\\n\", nbTestSamples,\n               (U32)testSamplesSize);\n  ctx->samples = samples;\n  ctx->samplesSizes = samplesSizes;\n  ctx->nbSamples = nbSamples;\n  ctx->nbTrainSamples = nbTrainSamples;\n  ctx->nbTestSamples = nbTestSamples;\n  /* Partial suffix array */\n  ctx->suffixSize = trainingSamplesSize - MAX(d, sizeof(U64)) + 1;\n  ctx->suffix = (U32 *)malloc(ctx->suffixSize * sizeof(U32));\n  /* Maps index to the dmerID */\n  ctx->dmerAt = (U32 *)malloc(ctx->suffixSize * sizeof(U32));\n  /* The offsets of each file */\n  ctx->offsets = (size_t *)malloc((nbSamples + 1) * sizeof(size_t));\n  if (!ctx->suffix || !ctx->dmerAt || !ctx->offsets) {\n    DISPLAYLEVEL(1, \"Failed to allocate scratch buffers\\n\");\n    COVER_ctx_destroy(ctx);\n    return 0;\n  }\n  ctx->freqs = NULL;\n  ctx->d = d;\n\n  /* Fill offsets from the samplesSizes */\n  {\n    U32 i;\n    ctx->offsets[0] = 0;\n    for (i = 1; i <= nbSamples; ++i) {\n      ctx->offsets[i] = ctx->offsets[i - 1] + samplesSizes[i - 1];\n    }\n  }\n  DISPLAYLEVEL(2, \"Constructing partial suffix array\\n\");\n  {\n    /* suffix is a partial suffix array.\n     * It only sorts suffixes by their first parameters.d bytes.\n     * The sort is stable, so each dmer group is sorted by position in input.\n     */\n    U32 i;\n    for (i = 0; i < ctx->suffixSize; ++i) {\n      ctx->suffix[i] = i;\n    }\n    /* qsort doesn't take an opaque pointer, so pass as a global.\n     * On OpenBSD qsort() is not guaranteed to be stable, their mergesort() is.\n     */\n    g_ctx = ctx;\n#if defined(__OpenBSD__)\n    mergesort(ctx->suffix, ctx->suffixSize, sizeof(U32),\n          (ctx->d <= 8 ? &COVER_strict_cmp8 : &COVER_strict_cmp));\n#else\n    qsort(ctx->suffix, ctx->suffixSize, sizeof(U32),\n          (ctx->d <= 8 ? &COVER_strict_cmp8 : &COVER_strict_cmp));\n#endif\n  }\n  DISPLAYLEVEL(2, \"Computing frequencies\\n\");\n  /* For each dmer group (group of positions with the same first d bytes):\n   * 1. For each position we set dmerAt[position] = dmerID.  The dmerID is\n   *    (groupBeginPtr - suffix).  This allows us to go from position to\n   *    dmerID so we can look up values in freq.\n   * 2. We calculate how many samples the dmer occurs in and save it in\n   *    freqs[dmerId].\n   */\n  COVER_groupBy(ctx->suffix, ctx->suffixSize, sizeof(U32), ctx,\n                (ctx->d <= 8 ? &COVER_cmp8 : &COVER_cmp), &COVER_group);\n  ctx->freqs = ctx->suffix;\n  ctx->suffix = NULL;\n  return 1;\n}\n\n/**\n * Given the prepared context build the dictionary.\n */\nstatic size_t COVER_buildDictionary(const COVER_ctx_t *ctx, U32 *freqs,\n                                    COVER_map_t *activeDmers, void *dictBuffer,\n                                    size_t dictBufferCapacity,\n                                    ZDICT_cover_params_t parameters) {\n  BYTE *const dict = (BYTE *)dictBuffer;\n  size_t tail = dictBufferCapacity;\n  /* Divide the data up into epochs of equal size.\n   * We will select at least one segment from each epoch.\n   */\n  const U32 epochs = MAX(1, (U32)(dictBufferCapacity / parameters.k / 4));\n  const U32 epochSize = (U32)(ctx->suffixSize / epochs);\n  size_t epoch;\n  DISPLAYLEVEL(2, \"Breaking content into %u epochs of size %u\\n\", epochs,\n               epochSize);\n  /* Loop through the epochs until there are no more segments or the dictionary\n   * is full.\n   */\n  for (epoch = 0; tail > 0; epoch = (epoch + 1) % epochs) {\n    const U32 epochBegin = (U32)(epoch * epochSize);\n    const U32 epochEnd = epochBegin + epochSize;"}}","role":"tool","tool_call_id":"call_-7246107219924609447"},{"content":"{"ok":true,"output":{"base_commit":"df09d4318f0f4f06d76c1e288732f5f9b1d9f59a","byte_count":2961,"end_line":409,"path":"lib/dictBuilder/cover.c","read_id":"887ca504f25eaa3718b64f55f3822be87caacf5f166230cc38c039d70e99e5a6","retrieval_handle":"observed-read:887ca504f25eaa3718b64f55f3822be87caacf5f166230cc38c039d70e99e5a6","source_revision":"base","source_sha256":"d00d66c3cf16663dbd9b00bf89dba2cea2d1f3fc5efc9d0394e588c64fdecb98","start_line":330,"total_lines":1090,"utf8":" * Called on each group of positions with the same dmer.\n * Counts the frequency of each dmer and saves it in the suffix array.\n * Fills `ctx->dmerAt`.\n */\nstatic void COVER_group(COVER_ctx_t *ctx, const void *group,\n                        const void *groupEnd) {\n  /* The group consists of all the positions with the same first d bytes. */\n  const U32 *grpPtr = (const U32 *)group;\n  const U32 *grpEnd = (const U32 *)groupEnd;\n  /* The dmerId is how we will reference this dmer.\n   * This allows us to map the whole dmer space to a much smaller space, the\n   * size of the suffix array.\n   */\n  const U32 dmerId = (U32)(grpPtr - ctx->suffix);\n  /* Count the number of samples this dmer shows up in */\n  U32 freq = 0;\n  /* Details */\n  const size_t *curOffsetPtr = ctx->offsets;\n  const size_t *offsetsEnd = ctx->offsets + ctx->nbSamples;\n  /* Once *grpPtr >= curSampleEnd this occurrence of the dmer is in a\n   * different sample than the last.\n   */\n  size_t curSampleEnd = ctx->offsets[0];\n  for (; grpPtr != grpEnd; ++grpPtr) {\n    /* Save the dmerId for this position so we can get back to it. */\n    ctx->dmerAt[*grpPtr] = dmerId;\n    /* Dictionaries only help for the first reference to the dmer.\n     * After that zstd can reference the match from the previous reference.\n     * So only count each dmer once for each sample it is in.\n     */\n    if (*grpPtr < curSampleEnd) {\n      continue;\n    }\n    freq += 1;\n    /* Binary search to find the end of the sample *grpPtr is in.\n     * In the common case that grpPtr + 1 == grpEnd we can skip the binary\n     * search because the loop is over.\n     */\n    if (grpPtr + 1 != grpEnd) {\n      const size_t *sampleEndPtr =\n          COVER_lower_bound(curOffsetPtr, offsetsEnd, *grpPtr);\n      curSampleEnd = *sampleEndPtr;\n      curOffsetPtr = sampleEndPtr + 1;\n    }\n  }\n  /* At this point we are never going to look at this segment of the suffix\n   * array again.  We take advantage of this fact to save memory.\n   * We store the frequency of the dmer in the first position of the group,\n   * which is dmerId.\n   */\n  ctx->suffix[dmerId] = freq;\n}\n\n/**\n * A segment is a range in the source as well as the score of the segment.\n */\ntypedef struct {\n  U32 begin;\n  U32 end;\n  U32 score;\n} COVER_segment_t;\n\n/**\n * Selects the best segment in an epoch.\n * Segments of are scored according to the function:\n *\n * Let F(d) be the frequency of dmer d.\n * Let S_i be the dmer at position i of segment S which has length k.\n *\n *     Score(S) = F(S_1) + F(S_2) + ... + F(S_{k-d+1})\n *\n * Once the dmer d is in the dictionay we set F(d) = 0.\n */\nstatic COVER_segment_t COVER_selectSegment(const COVER_ctx_t *ctx, U32 *freqs,\n                                           COVER_map_t *activeDmers, U32 begin,\n                                           U32 end,\n                                           ZDICT_cover_params_t parameters) {\n  /* Constants */\n  const U32 k = parameters.k;\n  const U32 d = parameters.d;"}}","role":"tool","tool_call_id":"call_-7246107219924609446"},{"content":"","reasoning_content":"The zstd fix for issue #1241 is commit "fix #1241: Ensure that first input position is valid for a match" — it's in COVER_buildDictionary / COVER_group? Let me recall actual upstream commit 25ba8ff "fix: COVER_best" no. Actually the upstream commit: https://github.com/facebook/zstd/commit/... "fix: dictionary builder: